"""Materialize checked-in PNG app icons using only the Python standard library."""
from pathlib import Path
import base64

ICONS = {'apple-touch-icon.png': '', 'icon-192.png': '', 'icon-512.png': '', 'favicon-32.png': ''}

def build(output="migration-public"):
    target = Path(output)
    target.mkdir(parents=True, exist_ok=True)
    for name, data in ICONS.items():
        (target / name).write_bytes(base64.b64decode(data))

if __name__ == "__main__":
    build()
